using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
namespace PZ3D {
 sealed class SafehouseTransferDictionary {
  public int FormatVersion,ItemCount;public string Hash,NonItemSignature;
  internal Dictionary<short,SafehouseTransferFormat.Item> Items;
  internal Dictionary<string,string> Categories;
 }
 sealed class SafehouseTransferPlan {
  public bool Supported;public string UnsupportedReason="";public string[] MissingTypes=new string[0];public int ChangedMappings;
  internal SafehouseTransferDictionary Source,Target;internal Dictionary<short,short> Mapping;internal HashSet<short> Missing;
 }
 sealed class SafehouseTransferChunk {
  public byte[] Bytes;public int WorldVersion;public long RecordCount,ItemQuantity,ItemsTransferred,ItemsRemoved,ItemsUnchanged,NestedRecords,ExtraReferences;
  public bool ItemCountKnown;public string CountUnknownReason="";public string UnsupportedReason="";public string[] DroppedTypes=new string[0];
 }
 // Deliberately limited to B42 world249's known item frames. This does not
 // reinterpret custom ModData numbers or promise a complete engine-world parser.
 static class SafehouseTransferFormat {
  internal sealed class Item {internal short Id;internal string Type;internal byte Flags;}
  sealed class Unsupported:Exception {internal Unsupported(string value):base(value){}}
  sealed class Reader {
   internal readonly byte[] Bytes;internal int Position,End;
   internal Reader(byte[] bytes,int start=0,int end=-1){Bytes=bytes;Position=start;End=end<0?bytes.Length:end;Need(0);}
   internal void Need(int n){if(n<0||Position<0||End>Bytes.Length||Position>End||n>End-Position)throw new InvalidDataException("二进制数据截断或长度越界。");}
   internal byte U8(){Need(1);return Bytes[Position++];}internal int I8(){return (sbyte)U8();}
   internal short I16(){return unchecked((short)((U8()<<8)|U8()));}
   internal int I32(){return unchecked((int)(((uint)U8()<<24)|((uint)U8()<<16)|((uint)U8()<<8)|U8()));}
   internal long I64(){return unchecked(((long)(uint)I32()<<32)|(uint)I32());}
   internal void Skip(int n){Need(n);Position+=n;}
   internal int Count(int maximum=100000){int n=I32();if(n<0||n>maximum)throw new InvalidDataException("字典或表条目数量无效。");return n;}
   internal string Text(){int n=I16();if(n<0)throw new InvalidDataException("文本长度无效。");Need(n);string result;try{result=new UTF8Encoding(false,true).GetString(Bytes,Position,n);}catch(DecoderFallbackException ex){throw new InvalidDataException("文本编码无效。",ex);}Position+=n;return result;}
  }
  sealed class Frame {internal int Offset,End,PrefixEnd,ExtendedFlags,ByteDataLength;internal int Quantity;internal List<int> Extra=new List<int>();internal Frame Parent;internal string Error;internal bool Removed;}
  sealed class ListFrame {internal int Start,End;internal List<Frame> Frames=new List<Frame>();internal bool Complete,TruncatedMarker;}
  static string Hash(byte[] b){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
  static string HashText(IEnumerable<string> rows){using(var stream=new MemoryStream()){foreach(string row in rows){byte[] bytes=Encoding.UTF8.GetBytes(row);stream.WriteByte((byte)(bytes.Length>>24));stream.WriteByte((byte)(bytes.Length>>16));stream.WriteByte((byte)(bytes.Length>>8));stream.WriteByte((byte)bytes.Length);stream.Write(bytes,0,bytes.Length);}return Hash(stream.ToArray());}}
  static string[] Strings(Reader r){int count=r.Count(65536);var result=new string[count];for(int i=0;i<count;i++)result[i]=r.Text();return result;}
  static int Index(Reader r,int count){int value=count>127?r.I16():r.I8();if(value<0||value>=count)throw new InvalidDataException("字典名称索引越界。");return value;}
  static Dictionary<short,Item> Infos(Reader r,string[] mods,string[] modules){int count=r.Count(65536);var rows=new Dictionary<short,Item>();var types=new HashSet<string>(StringComparer.Ordinal);for(int i=0;i<count;i++){short id=r.I16();string module=modules[Index(r,modules.Length)],name=r.Text();byte flags=r.U8();if((flags&~63)!=0||module.Length==0||name.Length==0)throw new InvalidDataException("字典条目标志或名称无效。");string type=module+"."+name;if(rows.ContainsKey(id)||!types.Add(type))throw new InvalidDataException("字典包含重复注册 ID 或类型。");rows.Add(id,new Item{Id=id,Type=type,Flags=flags});if((flags&1)!=0)Index(r,mods.Length);if((flags&16)!=0){int overrides=(flags&32)!=0?r.I8():1;if(overrides<0)throw new InvalidDataException("模组覆盖数量无效。");for(int q=0;q<overrides;q++)Index(r,mods.Length);}}return rows;}
  static string InfoSignature(Dictionary<short,Item> rows){return HashText(rows.OrderBy(p=>p.Key).Select(p=>p.Key+"|"+p.Value.Type+"|"+(p.Value.Flags&12)));}
  static string Registers(Reader r,bool scripts){int count=r.Count(1024);var groups=new SortedDictionary<string,string>(StringComparer.Ordinal);for(int i=0;i<count;i++){string name=r.Text();if(name.Length==0||groups.ContainsKey(name))throw new InvalidDataException("字典注册表名称重复或为空。");int size=r.Count(32*1024*1024),end;try{end=checked(r.Position+size);}catch(OverflowException){throw new InvalidDataException("字典注册表长度无效。");}r.Need(size);var block=new Reader(r.Bytes,r.Position,end);block.I16();int n=block.Count(65536);var rows=new SortedDictionary<short,string>();for(int q=0;q<n;q++){byte flags=block.U8();if((flags&~3)!=0)throw new InvalidDataException("字典注册表标志无效。");short id=block.I16();long version=scripts?block.I64():0;string text=block.Text();if(rows.ContainsKey(id)||text.Length==0)throw new InvalidDataException("字典注册表 ID 或文本无效。");rows.Add(id,flags+"|"+text+"|"+version);}if(block.Position!=end)throw new InvalidDataException("字典注册表含未知尾部数据。");r.Position=end;groups.Add(name,HashText(rows.Select(p=>p.Key+"|"+p.Value)));}return HashText(groups.Select(p=>p.Key+"|"+p.Value));}
  public static SafehouseTransferDictionary Load(string path){LauncherMaintenance.NoReparse(path);byte[] b;using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length<11||input.Length>32*1024*1024)throw new InvalidDataException("WorldDictionary 大小无效。");b=new byte[(int)input.Length];int at=0,n;while(at<b.Length&&(n=input.Read(b,at,b.Length-at))>0)at+=n;if(at!=b.Length)throw new InvalidDataException("WorldDictionary 未完整读取。");}return Parse(b);}
  static SafehouseTransferDictionary Parse(byte[] b){var r=new Reader(b);int version=r.I32();if(version!=1)throw new InvalidDataException("不支持的 WorldDictionary 格式："+version);r.I16();r.U8();r.I32();string[] mods=Strings(r),modules=Strings(r);var items=Infos(r,mods,modules);var categories=new Dictionary<string,string>();categories.Add("实体",InfoSignature(Infos(r,mods,modules)));int objectCount=r.Count(256);var objects=new SortedDictionary<int,string>();for(int i=0;i<objectCount;i++){int id=r.I8();string name=r.Text();if(objects.ContainsKey(id)||name.Length==0)throw new InvalidDataException("物体字典无效。");objects.Add(id,name);}categories.Add("物体",HashText(objects.Select(p=>p.Key+"|"+p.Value)));int spriteCount=r.Count(1000000);var sprites=new SortedDictionary<int,string>();for(int i=0;i<spriteCount;i++){int id=r.I32();string name=r.Text();if(sprites.ContainsKey(id)||name.Length==0)throw new InvalidDataException("贴图字典无效。");sprites.Add(id,name);}categories.Add("贴图",HashText(sprites.Select(p=>p.Key+"|"+p.Value)));categories.Add("字符串",Registers(r,false));categories.Add("脚本",Registers(r,true));if(r.Position!=b.Length)throw new InvalidDataException("WorldDictionary 含未知尾部数据。");return new SafehouseTransferDictionary{FormatVersion=version,ItemCount=items.Count,Hash=Hash(b),Items=items,Categories=categories,NonItemSignature=HashText(categories.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>p.Key+"|"+p.Value))};}
  public static SafehouseTransferPlan Plan(SafehouseTransferDictionary source,SafehouseTransferDictionary target){if(source==null||target==null)throw new ArgumentNullException();var plan=new SafehouseTransferPlan{Source=source,Target=target,Mapping=new Dictionary<short,short>(),Missing=new HashSet<short>()};foreach(var category in source.Categories)if(!target.Categories.ContainsKey(category.Key)||target.Categories[category.Key]!=category.Value){plan.UnsupportedReason="来源与目标的"+category.Key+"字典不同，当前版本不能安全转换这类引用。";return plan;}
   // Equal complete dictionaries need no rewrite, including entries already
   // retired in both saves. Preserve their existing engine interpretation.
   if(!string.IsNullOrEmpty(source.Hash)&&source.Hash==target.Hash){foreach(var item in source.Items.Values)plan.Mapping.Add(item.Id,item.Id);plan.Supported=true;return plan;}
   var byType=target.Items.Values.ToDictionary(i=>i.Type,StringComparer.Ordinal);var missing=new List<string>();foreach(var item in source.Items.Values){Item match;short id;if(!byType.TryGetValue(item.Type,out match)||(match.Flags&12)!=0){id=-1;missing.Add(item.Type);plan.Missing.Add(item.Id);}else id=match.Id;plan.Mapping.Add(item.Id,id);if(id!=item.Id)plan.ChangedMappings++;}plan.MissingTypes=missing.OrderBy(n=>n,StringComparer.Ordinal).ToArray();if(missing.Count>0&&target.Items.ContainsKey(-1)){plan.UnsupportedReason="目标字典占用了保留的 -1 ID，无法安全跳过缺失物品。";return plan;}plan.Supported=true;return plan;}
  static short Short(byte[] b,int offset){return unchecked((short)((b[offset]<<8)|b[offset+1]));}
  static int Int(byte[] b,int offset){return unchecked((int)(((uint)b[offset]<<24)|((uint)b[offset+1]<<16)|((uint)b[offset+2]<<8)|b[offset+3]));}
  static uint Crc(byte[] b,int start){uint crc=0xffffffff;for(int i=start;i<b.Length;i++){crc^=b[i];for(int q=0;q<8;q++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}return ~crc;}
  static bool Basic(byte[] b,int offset,out int end){end=0;if(offset<17||offset>b.Length-12)return false;int length=Int(b,offset);if(length<8||length>b.Length-offset-4||b[offset+6]!=255)return false;end=offset+4+length;return true;}
  static List<ListFrame> Lists(byte[] b){var result=new List<ListFrame>();for(int start=17;start<b.Length-12;start++){int count=Short(b,start);if(count<1)continue;int position=start+2;var list=new ListFrame{Start=start};for(int n=0;n<count;n++){int end;if(position>b.Length-11||Int(b,position)<1||Int(b,position)>1000000||b[position+10]!=255)break;int quantity=Int(b,position);if(!Basic(b,position+4,out end)){list.TruncatedMarker=quantity==1||list.Frames.Count>0;break;}long next=(long)end+(quantity-1)*4L;if(next>b.Length){list.TruncatedMarker=list.Frames.Count>0;break;}list.Frames.Add(new Frame{Offset=position+4,End=end,Quantity=quantity});position=(int)next;}if(list.Frames.Count==0&&!list.TruncatedMarker)continue;list.End=position;list.Complete=list.Frames.Count==count&&!list.TruncatedMarker;result.Add(list);}return result;}
  // A preceding item's final two data bytes can resemble another list count.
  // The complete containing list determines those exact same record boundaries;
  // its suffix aliases add no records and are not independent nested containers.
  static List<ListFrame> Canonical(List<ListFrame> lists){var complete=lists.Where(l=>l.Complete).ToArray();return lists.Where(candidate=>!complete.Any(cover=>candidate.Frames.Count>0&&candidate.Start>cover.Start&&candidate.End<=cover.End&&candidate.Frames.All(frame=>cover.Frames.Any(other=>other.Offset==frame.Offset&&other.End==frame.End&&other.Quantity==frame.Quantity)))).ToList();}
  static IEnumerable<Frame> WorldItems(byte[] b){for(int offset=39;offset<=b.Length-7;offset++){if(b[offset+6]!=255||b[offset-22]!=1||b[offset-21]!=6)continue;bool valid=true;for(int q=0;q<5;q++){byte[] bytes=b.Skip(offset-20+q*4).Take(4).Reverse().ToArray();float value=BitConverter.ToSingle(bytes,0);if(float.IsNaN(value)||float.IsInfinity(value)||Math.Abs(value)>1024){valid=false;break;}}if(valid){int end;if(Basic(b,offset,out end))yield return new Frame{Offset=offset,End=end,Quantity=1};else yield return new Frame{Offset=offset,End=b.Length,Quantity=1,Error="地面物品帧长度无效或被截断。"};}}}
  static void Table(Reader r,int depth){if(depth>32)throw new Unsupported("物品 ModData 表嵌套超过支持范围。");int count=r.Count(100000);if(count>(r.End-r.Position)/2)throw new Unsupported("物品 ModData 表长度无效。");for(int i=0;i<count;i++){Value(r,depth);Value(r,depth);}}
  static void Value(Reader r,int depth){int tag=r.U8();if(tag==0)r.Text();else if(tag==1)r.Skip(8);else if(tag==2)Table(r,depth+1);else if(tag==3){if(r.U8()>1)throw new Unsupported("物品 ModData 布尔值无效。");}else throw new Unsupported("不支持的物品 ModData 类型："+tag);}
  static void Visual(Reader r){int flags=r.U8();if((flags&~31)!=0)throw new Unsupported("不支持的物品外观标志。");for(int i=0;i<3;i++)r.Text();if((flags&1)!=0)r.Skip(3);if((flags&2)!=0)r.Skip(1);if((flags&4)!=0)r.Skip(1);if((flags&8)!=0)r.Skip(4);if((flags&16)!=0)r.Text();for(int i=0;i<6;i++)r.Skip(r.U8());}
  static void Prefix(byte[] b,Frame frame){try{var r=new Reader(b,frame.Offset+11,frame.End);int header=r.U8();if((header&128)!=0)throw new Unsupported("不支持的物品前缀标志。");if((header&1)!=0)r.Skip(4);if((header&4)!=0)r.Skip(1);if((header&8)!=0)Visual(r);if((header&16)!=0)r.Skip(4);if((header&32)!=0)r.Skip(4);if((header&64)!=0){int bits=r.I32();frame.ExtendedFlags=bits;if((bits&1)!=0)Table(r,0);if((bits&4)!=0)r.Skip(2);if((bits&8)!=0)r.Text();if((bits&16)!=0){frame.ByteDataLength=r.Count(32*1024*1024);r.Skip(frame.ByteDataLength);}if((bits&32)!=0){int count=r.Count(100000);if(count>(r.End-r.Position)/2)throw new Unsupported("物品额外引用数量无效。");for(int i=0;i<count;i++){frame.Extra.Add(r.Position);r.Skip(2);}}}frame.PrefixEnd=r.Position;}catch(InvalidDataException ex){frame.Error="已识别的物品前缀无法完整解析："+ex.Message;}catch(Unsupported ex){frame.Error=ex.Message;}}
  static bool Opaque(Frame child,Frame parent){return child.Offset>parent.Offset&&parent.PrefixEnd>0&&child.Offset>=parent.Offset+7&&child.End<=parent.PrefixEnd;}
  static SafehouseTransferChunk Reject(SafehouseTransferChunk result,string reason){result.Bytes=null;result.UnsupportedReason=reason;return result;}
  public static SafehouseTransferChunk TransformChunk(byte[] raw,SafehouseTransferPlan plan){if(raw==null||plan==null)throw new ArgumentNullException();if(raw.Length<17||Int(raw,5)!=raw.Length)throw new InvalidDataException("地图区块头部或内部长度无效。");uint crc=Crc(raw,17);if(Int(raw,9)!=0||(uint)Int(raw,13)!=crc)throw new InvalidDataException("地图区块 CRC 校验失败。");var result=new SafehouseTransferChunk{WorldVersion=Int(raw,1)};if(!plan.Supported)return Reject(result,plan.UnsupportedReason);if(result.WorldVersion!=249)return Reject(result,"当前仅支持 B42 world249 区块，来源版本为 "+result.WorldVersion+"。");if(raw[0]!=0)return Reject(result,"当前不支持调试格式地图区块。");if(raw.Length>32*1024*1024)return Reject(result,"地图区块超过当前转换大小限制。");
   bool identity=plan.ChangedMappings==0&&plan.MissingTypes.Length==0&&plan.Missing.Count==0&&!string.IsNullOrEmpty(plan.Source.Hash)&&plan.Source.Hash==plan.Target.Hash;var census=Census(raw,plan,result);if(identity&&census.Bytes==null)return new SafehouseTransferChunk{Bytes=(byte[])raw.Clone(),WorldVersion=result.WorldVersion,ItemCountKnown=false,CountUnknownReason="区块已原样保留，物品数量未统计："+census.UnsupportedReason};return census;
  }
  static SafehouseTransferChunk Census(byte[] raw,SafehouseTransferPlan plan,SafehouseTransferChunk result){
   var lists=Canonical(Lists(raw));var all=new Dictionary<int,Frame>();bool quantityCollision=false;foreach(var frame in lists.Where(l=>l.Complete).SelectMany(l=>l.Frames).Concat(WorldItems(raw))){Frame existing;if(all.TryGetValue(frame.Offset,out existing)){if(existing.End!=frame.End||existing.Quantity!=frame.Quantity)quantityCollision=true;}else all.Add(frame.Offset,frame);}foreach(var frame in all.Values)if(frame.Error==null)Prefix(raw,frame);var frames=all.Values.Where(child=>!all.Values.Any(parent=>Opaque(child,parent))).OrderBy(f=>f.Offset).ToList();if(quantityCollision)return Reject(result,"物品帧数量存在歧义，已拒绝转换。");foreach(var incomplete in lists.Where(l=>!l.Complete)){if(!all.Values.Any(parent=>parent.PrefixEnd>0&&incomplete.Start>=parent.Offset+7&&incomplete.Start<parent.PrefixEnd))return Reject(result,"识别到不完整的容器物品列表，已拒绝整个区块。");}
   // A complete census requires the same supported framing as a conversion.
   // Identity copies may preserve unknown payloads, but must not claim their count.
   if(frames.Count==0)return Reject(result,"无法证明区块中的物品引用已完整解析，当前不能跨字典转换。");
   foreach(var frame in frames){if(frame.Error!=null)return Reject(result,frame.Error);short id=Short(raw,frame.Offset+4);if(!plan.Source.Items.ContainsKey(id))return Reject(result,"已识别物品的源注册 ID 不在来源字典中："+id);foreach(var other in frames){if(other==frame)continue;if(other.Offset<frame.Offset&&frame.Offset<other.End&&frame.End>other.End)return Reject(result,"物品帧发生部分重叠，不能安全转换。");if(other.Offset<frame.Offset&&frame.End<=other.End){if(frame.Offset<other.PrefixEnd)return Reject(result,"物品帧与已解析前缀边界冲突。");if(frame.Parent==null||other.End-other.Offset<frame.Parent.End-frame.Parent.Offset)frame.Parent=other;}}}
   foreach(var frame in frames){if(frame.ByteDataLength>0)return Reject(result,"物品包含内嵌对象数据（例如尸体及其物品），当前不能安全跨字典转换。");if((frame.ExtendedFlags&~127)!=0)return Reject(result,"物品包含尚未完整解析的附加字段，当前不能安全跨字典转换。");if(frame.PrefixEnd!=frame.End)return Reject(result,"物品包含尚未完整解析的子类或嵌套数据（例如武器配件或容器），当前不能安全跨字典转换。");}
   // Other world objects (for example IsoTrap) also call saveWithSize. A known
   // list/world-item match is not evidence that every other frame is accounted for.
   for(int offset=17;offset<=raw.Length-12;offset++){int end;if(Basic(raw,offset,out end)&&!frames.Any(frame=>frame.Offset==offset))return Reject(result,"发现尚未识别所属物体结构的物品帧（例如陷阱中的武器），当前不能安全跨字典转换。");}
   foreach(var list in lists.Where(l=>l.Complete)){if(frames.Any(parent=>list.Start>parent.Offset&&list.Start<parent.End&&list.End>parent.End))return Reject(result,"嵌套容器列表超出所属物品边界。");}
   foreach(var frame in frames){if(frame.Parent!=null){result.NestedRecords++;if(frame.Parent.Quantity!=1)return Reject(result,"带内容的堆叠容器数量结构暂未支持。");}for(Frame current=frame;current!=null;current=current.Parent)if(plan.Missing.Contains(Short(raw,current.Offset+4)))frame.Removed=true;foreach(int offset in frame.Extra){short id=Short(raw,offset);if(!plan.Source.Items.ContainsKey(id))return Reject(result,"物品额外引用的源 ID 不在字典中："+id);if(plan.Missing.Contains(id))return Reject(result,"物品额外引用包含目标缺失类型，暂不支持安全删除这类引用："+plan.Source.Items[id].Type);}}
   var dropped=new HashSet<string>(StringComparer.Ordinal);byte[] output=(byte[])raw.Clone();foreach(var frame in frames){short source=Short(raw,frame.Offset+4),target=plan.Mapping[source];output[frame.Offset+4]=(byte)(target>>8);output[frame.Offset+5]=(byte)target;result.RecordCount++;result.ItemQuantity+=frame.Quantity;if(frame.Removed){result.ItemsRemoved+=frame.Quantity;dropped.Add(plan.Source.Items[source].Type);}else{result.ItemsTransferred+=frame.Quantity;if(source==target)result.ItemsUnchanged+=frame.Quantity;}foreach(int offset in frame.Extra){short value=plan.Mapping[Short(raw,offset)];output[offset]=(byte)(value>>8);output[offset+1]=(byte)value;result.ExtraReferences++;}}uint converted=Crc(output,17);output[13]=(byte)(converted>>24);output[14]=(byte)(converted>>16);output[15]=(byte)(converted>>8);output[16]=(byte)converted;result.DroppedTypes=dropped.OrderBy(t=>t,StringComparer.Ordinal).ToArray();result.Bytes=output;result.ItemCountKnown=true;return result;
  }
 }
}
